-- Calibration is recorded in one place: FRM-705 (owner's decision, 2026-10-08).
--
-- Until now the probe thermometer's ice-point check and the refrigerator and freezer sensor
-- comparisons were recorded on FRM-401 (under SOP-401), and every other device on FRM-705 (under
-- FSQM-030). FRM-705 listed the probe and the sensors too and pointed back at FRM-401. SOP-401 Part 6
-- already said the checks would move once the site had a single calibration program.
--
--   FRM-705  New -> v2   the probe has one row per check (ice point, boiling water); the sensor rows
--                        take their readings here; the outcome "Recorded on FRM-401" is removed.
--   FRM-401  v2  -> v3   the accuracy section becomes one confirmation that the month's FRM-705 was
--                        passed, with a link to it. Six fields leave the form; entries filled under
--                        v2 or New keep their answers and are shown with the form they were filled on.
--   SOP-401  v2  -> v3   Part 6 points to FSQM-030 and FRM-705. Ice-point tolerance +/-1 F -> +/-2 F.
--   FSQM-030 New -> v2   both probe checks and the sensor comparisons are recorded on FRM-705.
--
-- Approved by GJM, effective 2026-10-08.
--
-- Each document is changed only if it still holds exactly what this file was written against
-- (md5 of the parts replaced). A document already holding the new text is left alone, so the file
-- can be run twice. Anything else stops the migration.

do $$
declare
  d record;
  target jsonb;
  new_content jsonb;
begin
  -- FRM-705  New -> v2
  select id, revision, status, content into d from public.sop_documents where sop_number = 'FRM-705';
  if not found then
    raise exception 'FRM-705: document not found';
  end if;
  target := $jfrm705${"form_schema":{"schemaVersion":1,"sections":[{"fields":[{"id":"how_this_works","label":"Calibration directory and monthly checks","text":"THE ROWS BELOW ARE THE DIRECTORY (SQF 11.2.3.6): every device used to monitor a critical control point, a prerequisite program or a specification. One entry is made each month, and every device gets an outcome.\n\nCheck the probe thermometer first (ice point, then boiling water): it is the reference for the sensor and oven rows. Open a row to see how to check it. Record what the reference read and what the device read - numbers, not just a tick.\n\nA FAIL IS NOT THE END OF THE ROW. Record what was done, and tell the SQF Practitioner the same day: product made since the last pass may need to be held (FSQM-030 Part 5).\n\nADD A DEVICE when one is bought, and delete a row only when the device leaves the site.","type":"info"}],"id":"about","title":"1. How this record works"},{"fields":[{"help":"e.g. October 2026","id":"check_month","label":"Month","required":true,"showInList":true,"type":"text","width":"third"},{"defaultToday":true,"id":"check_date","label":"Date checked","required":true,"type":"date","width":"third"},{"columns":[{"id":"device_id","label":"ID / serial","type":"text"},{"id":"used_for","label":"Used for","type":"text","width":2},{"id":"method","label":"Method and reference","type":"text","width":2},{"id":"tolerance","label":"Tolerance","type":"text","width":2},{"id":"reference_reading","label":"Reference read","type":"text"},{"id":"device_reading","label":"Device read","type":"text"},{"id":"outcome","label":"Outcome","options":["Pass","Fail - action recorded","Not relied on","Not checked this month - reason recorded"],"required":true,"type":"select"},{"id":"action","label":"Action taken","type":"text","width":2}],"id":"devices","label":"Directory and results","rowDialog":true,"rows":{"addLabel":"Add device","defaultValues":[{"device_id":"","method":"Ice water (ice point)","tolerance":"32°F ±2°F","used_for":"Reference for every other temperature check on this record"},{"device_id":"","method":"Boiling water","tolerance":"Within ±2°F of the site's boiling point","used_for":"Reference for every other temperature check on this record"},{"device_id":"d88b4c010010b5da","method":"Compared with the probe, same place, same time","tolerance":"±2°F of the probe","used_for":"Cold storage PRP (SOP-401)"},{"device_id":"d88b4c010010b513","method":"Compared with the probe, same place, same time","tolerance":"±2°F of the probe","used_for":"Cold storage PRP (SOP-401)"},{"device_id":"","method":"Probe (oven-safe) at the centre of the rack after preheat, compared with the display","tolerance":"Oven not more than 5°F cooler than its display","used_for":"CCP 1 (FRM-507): at least 350°F"},{"device_id":"","method":"Timed against a phone clock over a full bake","tolerance":"±30 seconds over 27 minutes","used_for":"CCP 1 (FRM-507): at least 27 minutes"},{"device_id":"","method":"25 lb certified test weight","tolerance":"25 lb ±0.25 lb (±1%)","used_for":"Weighing ingredients (SOP-506)"},{"device_id":"","method":"25 lb certified test weight","tolerance":"25 lb ±0.25 lb (±1%)","used_for":"Weighing ingredients (SOP-506)"},{"device_id":"","method":"Not calibrated","tolerance":"Not relied on","used_for":"CCP 2 (FRM-606) - reading recorded, not judged"}],"deletable":true,"guidance":["• Fill a cup with crushed ice, top it up with cold water, stir, and leave it for a minute.\n• Hold the probe in the centre of the cup, clear of the sides and bottom, until the reading settles.\n• Reference read = 32. Device read = what the probe shows.\n• Outside tolerance: adjust the probe to 32°F if it can be adjusted and check again. A probe that cannot be brought within tolerance is not used as the reference until it is replaced.","• Bring water to a full rolling boil, hold the probe in it clear of the pan, and let the reading settle.\n• Reference read = the site's boiling point, written in the Tolerance column the first time and reused. Device read = what the probe shows.\n• Outside tolerance: the probe is not used as the reference until it is replaced.","• Do the two probe rows first. A probe that has not passed is not used for this comparison.\n• Hold the probe beside the unit's sensor, both reading the same place at the same time, and let the probe settle.\n• Reference read = the probe. Device read = the sensor, from the YoLink app or the Team App's Temperature Monitoring page.\n• More than 2°F apart: record Fail. The sensor is suspect - tell the SQF Practitioner, and arrange for it to be replaced or checked again before next month. Until then its readings are confirmed with the probe.\n• A unit that is out of service: 'Not checked this month - reason recorded'.","• Do the two probe rows first. A probe that has not passed is not used for this comparison.\n• Hold the probe beside the unit's sensor, both reading the same place at the same time, and let the probe settle.\n• Reference read = the probe. Device read = the sensor, from the YoLink app or the Team App's Temperature Monitoring page.\n• More than 2°F apart: record Fail. The sensor is suspect - tell the SQF Practitioner, and arrange for it to be replaced or checked again before next month. Until then its readings are confirmed with the probe.\n• A unit that is out of service: 'Not checked this month - reason recorded'.","• Preheat to the bake setting. Place the probe's oven-safe tip at the centre of the rack, close the door, wait for the reading to settle.\n• Record the probe reading and the display reading.\n• If the oven is more than 5°F cooler than its display: record Fail, tell the SQF Practitioner the same day. Until the oven is serviced, the set point is raised so the probe reads at least 350°F.","• Start the phone stopwatch when the bake timer starts; stop it when the timer ends. Record both times.","• Zero the empty, clean platform. Place the 25 lb certified test weight in the centre. Record the reading.\n• Outside tolerance: tag the scale DO NOT USE and tell the SQF Practitioner. Re-calibrate with the scale's own calibration routine (manual), then check again.","• As for bench scale 1.","• Mark 'Not relied on'. CCP 2 is judged by the visual check and the pull test, not by this gauge.\n• The gauge is calibrated before any CCP 2 limit is set on it (FSQM-016, task 14.8)."],"labelHeader":"Device","labels":["Probe thermometer - ice point (site reference)","Probe thermometer - boiling water (site reference)","Walk-in refrigerator sensor (YoLink)","Walk-in freezer sensor (YoLink)","Revent 724 oven - temperature display","Revent 724 oven - bake timer","Bench scale 1 - OHAUS Defender 3000 i-DT33","Bench scale 2","Vacuum sealer - vacuum gauge"],"mode":"fixed"},"type":"grid"},{"id":"checked_by","label":"Checked by","required":true,"role":"filler","statement":"I performed the checks recorded above on the date shown.","type":"signature"}],"id":"checks","title":"2. Checks"},{"fields":[{"id":"any_fail","label":"Any device failed this month?","options":["No","Yes - product assessed under FSQM-030 Part 5"],"required":true,"type":"select","width":"half"},{"id":"review_notes","label":"Product assessed, held or released; follow-up","type":"textarea"},{"id":"reviewed_by","label":"Reviewed by the SQF Practitioner","required":true,"role":"verifier","statement":"I have reviewed these checks and any failure has been dealt with.","type":"signature"}],"id":"review","title":"3. Review"}],"settings":{"allowMultipleDrafts":true,"attachmentsEnabled":true,"instanceTitleTemplate":"Calibration checks - {check_month}","requireVerification":true}}}$jfrm705$::jsonb;
  if d.revision = 'v2' and (select bool_and(d.content->k = target->k) from unnest(array['form_schema']) k) then
    raise notice 'FRM-705: already at v2, left alone';
  elsif d.revision = 'New' and d.status = 'active'
        and md5((select jsonb_object_agg(k, d.content->k) from unnest(array['form_schema']) k)::text) = 'd908a77e0a6bf39f2f0b3ea0d1b2c540' then
    new_content := d.content || target;
    update public.sop_documents
       set content = new_content, revision = 'v2', effective_date = '2026-10-08', approved_by = 'GJM'
     where id = d.id;
  else
    raise exception 'FRM-705: not in the state this migration was written against (revision %, status %)', d.revision, d.status;
  end if;

  -- FRM-401  v2 -> v3
  select id, revision, status, content into d from public.sop_documents where sop_number = 'FRM-401';
  if not found then
    raise exception 'FRM-401: document not found';
  end if;
  target := $jfrm401${"form_schema":{"schemaVersion":1,"sections":[{"fields":[{"id":"review_intro","label":"Before you start","text":"One record per month. This is the verification that the automatic monitoring worked (SQF 2.5.2.1) — it is not the temperature record itself, which the sensors keep continuously.\n\nOpen Compliance → Temperature Monitoring, set the range to the month you are reviewing, and read the figures from the Summary by Equipment table and the alert list.\n\nOnly the SQF Practitioner signs this record (SOP-401 Part 6).","type":"info"},{"help":"e.g. September 2026","id":"review_month","label":"Month reviewed","required":true,"showInList":true,"type":"text","width":"half"},{"id":"review_date","label":"Date of review","required":true,"showInList":true,"type":"date","width":"half"}],"id":"header","title":"Month under review"},{"fields":[{"columns":["Unit","Sensor","Limit","Notes"],"id":"limits_table","label":"Unit limits (SOP-401 Part 2)","rows":[["Walk-In Refrigerator","d88b4c010010b5da","At or below 41 °F","TCS ingredients — butter, liquid eggs"],["Walk-In Freezer","d88b4c010010b513","At or below 10 °F","Only while in service. See SOP-401 Part 7"],["Bakery Floor","d88b4c010010b70a","No limit","Ambient production area, not a storage unit"]],"type":"reference_table"}],"id":"limits_ref","title":"Limits this review is judged against"},{"fields":[{"columns":[{"id":"state","label":"State this month","options":["In service","Out of service","Not a storage unit","Changed during the month"],"required":true,"type":"select","width":2},{"id":"min_f","label":"Min °F","type":"text","width":1},{"id":"max_f","label":"Max °F","type":"text","width":1},{"id":"avg_f","label":"Avg °F","type":"text","width":1},{"id":"held_limit","label":"Held its limit all month","type":"pass_fail","width":1},{"help":"\"None\" is an answer. A gap nobody can explain is a finding — say so.","id":"gaps","label":"Gaps in logging (and why)","type":"text","width":3}],"help":"Read Min/Max/Avg from the Summary by Equipment table with the range set to this month. Leave a unit's temperatures blank if it was out of service all month, and say so in the state column.","id":"unit_summary","label":"Temperature summary","rows":{"defaultValues":[{"state":"In service"},{"state":"In service"},{"state":"Not a storage unit"}],"deletable":true,"labelHeader":"Unit","labels":["Walk-In Refrigerator","Walk-In Freezer","Bakery Floor"],"mode":"fixed"},"type":"grid"}],"id":"unit_month","title":"The month, by unit"},{"fields":[{"id":"alerts_intro","label":"","text":"List every alert the Team App raised this month, from the Temperature Alerts panel. If none were raised, add one row and write \"No alerts raised\" — a blank section does not distinguish a quiet month from an unreviewed one.","type":"info"},{"columns":[{"id":"unit","label":"Unit","type":"text","width":2},{"id":"kind","label":"Alert","options":["Out of range","No data","Low battery","No alerts raised"],"type":"select","width":2},{"id":"opened","label":"Opened","type":"date","width":2},{"id":"worst","label":"Worst reading","type":"text","width":1},{"id":"acknowledged","label":"Acknowledged with an action","type":"pass_fail","width":1},{"id":"action_adequate","label":"Action was appropriate","type":"pass_fail","width":1},{"help":"FRM-702 hold number and/or FRM-007 CAPA number, or \"none\".","id":"product_affected","label":"Product affected — hold / CAPA reference","type":"text","width":3}],"id":"alert_log","label":"Alerts","rows":{"addLabel":"Add alert","mode":"dynamic"},"type":"grid"}],"id":"alerts","title":"Alerts raised this month"},{"fields":[{"id":"accuracy_intro","label":"","text":"The accuracy of the probe thermometer and of each unit's sensor is checked every month under FSQM-030 and recorded on FRM-705, with the site's other measuring devices. It is not recorded again here.\n\nOpen the month's FRM-705 and confirm below what it shows.","type":"info"},{"help":"Fail if the month has no FRM-705, or if the probe or a sensor failed on it.","id":"calibration_confirmed","label":"FRM-705 for this month shows the probe thermometer and each in-service unit's sensor within tolerance","linkTo":{"form":"FRM-705","latestEntry":true},"required":true,"type":"pass_fail","width":"full"},{"id":"calibration_note","label":"If it failed: what was found and what is being done","type":"text","width":"full"}],"id":"accuracy","title":"Device accuracy (recorded on FRM-705)"},{"fields":[{"columns":[{"id":"taken_at","label":"Date & time","type":"datetime","width":2},{"id":"unit","label":"Unit","type":"text","width":2},{"id":"reading_f","label":"Reading °F","type":"text","width":1},{"id":"within_limit","label":"Within limit","type":"pass_fail","width":1},{"id":"taken_by","label":"Taken by","type":"text","width":2}],"help":"Start and end of each production day, for each affected in-service unit. Leave empty if no sensor was down this month.","id":"manual_readings","label":"Manual readings taken while a sensor was down (SOP-401 Part 5)","rows":{"addLabel":"Add reading","mode":"dynamic"},"type":"grid"},{"columns":[{"id":"unit","label":"Unit","type":"text","width":2},{"id":"change","label":"Change","options":["Placed out of service","Returned to service"],"type":"select","width":2},{"id":"changed_on","label":"Date","type":"date","width":2},{"id":"reason","label":"Reason","type":"text","width":3},{"id":"return_conditions","label":"Return conditions met (clean, inspected, reporting, 24 h at limit)","type":"pass_fail","width":2},{"id":"food_placed_on","label":"Food first placed in unit","type":"date","width":2}],"help":"Leave empty if nothing changed. A return to service needs the 24-hour hold at limit recorded before food went in.","id":"service_changes","label":"Units placed in or out of service this month (SOP-401 Part 7)","rows":{"addLabel":"Add change of state","mode":"dynamic"},"type":"grid"}],"id":"manual_state","title":"Manual readings and changes of state"},{"fields":[{"id":"facility_check","label":"FRM-913's 11.6.2 Cold Storage line was completed this month (SOP-401 Part 8)","type":"pass_fail","width":"full"},{"help":"Alerts were raised where they should have been, reached someone, and were acted on.","id":"system_effective","label":"The monitoring system worked this month","required":true,"type":"pass_fail","width":"full"},{"help":"Repeat excursions on the same unit, a drifting sensor, unexplained gaps. \"Nothing to report\" is an acceptable answer and is better than a blank.","id":"findings","label":"Findings, trends and anything carried forward","type":"textarea","width":"full"},{"id":"capa_raised","label":"CAPA raised as a result of this review (FRM-007 number, or \"none\")","type":"text","width":"half"},{"id":"reviewed_by","label":"Reviewed by (SQF Practitioner)","role":"verifier","statement":"I reviewed this month's temperature monitoring, the alerts raised and how they were closed, and the month's calibration record (FRM-705), and I am satisfied the monitoring performed as SOP-401 requires.","type":"signature","width":"half"}],"id":"conclusion","title":"Conclusion and signature"}],"settings":{"allowMultipleDrafts":false,"attachmentsEnabled":true,"instanceTitleTemplate":"Temperature review — {review_month}"}}}$jfrm401$::jsonb;
  if d.revision = 'v3' and (select bool_and(d.content->k = target->k) from unnest(array['form_schema']) k) then
    raise notice 'FRM-401: already at v3, left alone';
  elsif d.revision = 'v2' and d.status = 'active'
        and md5((select jsonb_object_agg(k, d.content->k) from unnest(array['form_schema']) k)::text) = '90279a9b3193085f7282c5d64a57ffc4' then
    new_content := d.content || target;
    update public.sop_documents
       set content = new_content, revision = 'v3', effective_date = '2026-10-08', approved_by = 'GJM'
     where id = d.id;
  else
    raise exception 'FRM-401: not in the state this migration was written against (revision %, status %)', d.revision, d.status;
  end if;

  -- SOP-401  v2 -> v3
  select id, revision, status, content into d from public.sop_documents where sop_number = 'SOP-401';
  if not found then
    raise exception 'SOP-401: document not found';
  end if;
  target := $jsop401${"form_references":"FRM-401 Temperature Monitoring Review; FRM-705 Calibration Directory and Check Record; FRM-702 Non-Conforming Material Hold & Tagging Record; FRM-913 Facility & Equipment Inspection","governing_reference":"SQF Food Safety Code: Food Manufacturing, Edition 9 — 11.6.2 Cold Storage, Freezing and Chilling of Foods: 11.6.2.1 performance and capacity, 11.6.2.2 construction and cleanability, 11.6.2.3 monitoring, frequency of checks, corrective action out of specification, and records, 11.6.2.4 drainage of defrost and condensate water.\nSQF Food Safety Code: Food Manufacturing, Edition 9 — 2.5.2.1 Verification of monitoring activities, which the monthly review on FRM-401 performs.\nFSQM-018 Non-Conforming Product and Equipment — where product affected by an excursion is held and dispositioned.\nFSQM-009 Corrective and Preventive Action (CAPA) Program — where an excursion or a facility defect meets one of its Part 3 triggers.\nFSQM-030 Calibration Program — under which the probe thermometer and the sensors are checked each month and recorded on FRM-705.","procedure":["Units and their state","> The site has three temperature sensors. Two are in storage units that are judged against a limit; the third monitors the production area and is not a storage unit.","• Walk-In Refrigerator (sensor d88b4c010010b5da) — holds butter, liquid eggs and other refrigerated ingredients. In service. Its sensor is placed at the unit's warmest point, next to the door, which is where SQF 11.6.2.3 requires the monitoring equipment to sit.","• Walk-In Freezer (sensor d88b4c010010b513) — in service. The vegan burger line it held was discontinued in June 2026, so it currently holds no product; it nonetheless remains switched on and monitored against its limit, because a running unit that cannot hold temperature is worth knowing about. It is placed out of service only when it is switched off — see Part 7 before any food is placed in it.","• Bakery Floor (sensor d88b4c010010b70a) — ambient monitoring of the production area. It is not a storage unit, no temperature limit applies to it, and it raises no alert.","> The current state of every unit, its limit and who its alerts go to are held in the Team App under Compliance → Temperature Monitoring. That page is the controlled record of those settings; this procedure states them so that a reader on paper knows what they should be.","> A temperature reading for each in-service unit shall be readable without entering the unit, so that a unit can be checked without opening the door. The sensors carry no local display: the reading is taken from the YoLink app and from the Team App's Temperature Monitoring page, both of which show each unit's current temperature without the door being opened.","Limits","• Walk-In Refrigerator: at or below 41 °F.","• Walk-In Freezer, while in service: at or below 10 °F.","> A reading exactly at the limit passes; a reading beyond it fails. 41 °F is the temperature at or below which time/temperature control for safety foods must be held. The refrigerator has never exceeded it in the logged history, so the limit reflects what the unit actually does rather than setting a target it will breach on an ordinary day.","> Limits are changed only by the SQF Practitioner, in the Team App. A limit change takes effect immediately for all subsequent readings and is not applied backwards.","Monitoring — the alert is the check","> Each sensor reports continuously, roughly hourly, and every reading is retained. The Team App examines those readings every fifteen minutes and raises an alert in any of three cases:","• Out of range — the two most recent readings from an in-service unit are both beyond its limit. Two readings, not one, so that a door held open while ingredients are carried out does not raise an alert.","• No data — nothing has been logged for the unit for more than six hours.","• Low battery — the sensor reports a low battery, which is how a unit stops being monitored.","> This automated check is the monitoring check required by SQF 11.6.2.3, and its frequency is every fifteen minutes. There is no separate daily manual temperature round: with continuous logging and an automatic check, a once-a-day reading would add work and detect less. What the site does instead is verify monthly that the system worked — Part 6 and FRM-401.","> An alert is sent by email to the recipients recorded against the unit and appears on the Temperature Monitoring page. An alert that nobody has responded to is re-sent every twenty-four hours until it is acknowledged.","Responding to an out-of-range alert","• Go to the unit. Check that the door is shut and sealing, that nothing is blocking the airflow or piled against the evaporator, and that the unit is running.","• Take a reading with the probe thermometer and compare it to what the sensor is reporting.","• Correct what you can — close the door, move what is blocking the airflow, restart the unit.","• If the unit cannot be brought back within its limit, tell the SQF Practitioner immediately and move the product to another unit that can hold it.","• Acknowledge the alert in the Team App, saying what you found and what you did.","> The acknowledgment is the corrective action record that SQF 11.6.2.3 requires. It is written once and cannot be edited afterwards, so write what actually happened, including the time and the probe reading.","> The SQF Practitioner decides what happens to any product that was in the unit. Product whose safety or quality is in doubt is placed on Hold under FSQM-018 Non-Conforming Product and Equipment and recorded on FRM-702; it is not released or used until that hold is dispositioned. A corrective and preventive action is raised under FSQM-009 where one of its Part 3 triggers is met — a repeat excursion on the same unit being the usual one.","Responding to a no-data or low-battery alert","> A sensor that has stopped reporting does not mean the unit is fine. It means nobody knows, and the unit is unmonitored until it reports again. Logging stopped three times in the first ten weeks of monitoring — once for more than three days — and nobody noticed, which is why absence of data raises an alert of its own.","• Check that the sensor has power and replace the battery if it is low.","• Until logging resumes, read each affected in-service unit at the start and at the end of each production day and record those readings on FRM-401.","• If logging cannot be restored the same day, tell the SQF Practitioner.","• Acknowledge the alert in the Team App with what was done.","Monthly review and device accuracy","> Once a month the SQF Practitioner reviews the previous month on FRM-401 and signs it. This is the verification activity required by SQF 2.5.2.1: the alert does the monitoring, and this confirms the monitoring worked.","• Confirm that each in-service unit held its limit for the month, and record the minimum, maximum and average from the Temperature Monitoring page.","• Confirm that every alert raised in the month was acknowledged, and that the action recorded was appropriate.","• Confirm that there were no unexplained gaps in logging.","• Confirm on FRM-401 that the month's calibration check is recorded on FRM-705 and that the probe thermometer and each in-service unit's sensor passed.","> The accuracy of the probe thermometer and of the sensors is checked every month under FSQM-030 Calibration Program and recorded on FRM-705, with the site's other measuring devices: the probe in ice water and in boiling water, each within ±2 °F, and each in-service unit's sensor against the probe, within ±2 °F. It is recorded there once and not again on FRM-401.","> A sensor that fails is treated as suspect: its readings are confirmed with the probe until it is replaced or passes a check.","Out of service, and return to service","> A storage unit that holds no food may be placed out of service so that it is not alerted on, and may then be switched off. This is a recorded decision, not simply switching a unit off.","• Only the SQF Practitioner places a unit in or out of service, in the Team App, recording the reason.","• While a unit is out of service its readings are not judged against its limit and no alert is raised for it.","• No food of any kind may be stored in an out-of-service unit.","> Before a unit is returned to service and any food is placed in it, all of the following shall be true: it has been cleaned and sanitized; it has been inspected and found in good repair, with door seals intact; its sensor is reporting; and it has held at or below its limit continuously for twenty-four hours.","• The SQF Practitioner records the return to service on FRM-401, including the twenty-four hour hold and the date food was first placed in the unit.","Condition, capacity and drainage of the units","> SQF 11.6.2 asks more of cold storage than a temperature. The units themselves shall be capable of holding the site's maximum expected volume at the required temperature, be constructed so that they can be cleaned and maintained, and drain their defrost and condensate water to the site's drainage system rather than onto the floor or onto stored product.","• These were confirmed at issue of this procedure, on 2026-09-08: both units were found sound, cleanable, and of adequate capacity for the site's maximum expected volume; both hold packaged product only, with no exposed product; and the defrost and condensate water of each unit drains to the site drain or to the outside of the facility, not onto the floor or onto stored product. Photographs of both units and of their drain lines are retained. They are re-inspected monthly on FRM-913 under its 11.6.2 Cold Storage line, which is where facility condition is already recorded.","• A defect found in a unit's condition, capacity or drainage is raised as a corrective and preventive action under FSQM-009 and repaired.","> The monthly facility inspection carries this, rather than a second inspection of its own, so that a defect in a walk-in is found and closed the same way as a defect anywhere else in the plant."],"records":"FRM-401 Temperature Monitoring Review — one per month, carrying the month's temperature summary per unit, the alerts raised and how they were closed, confirmation that the month's calibration check (FRM-705) was passed, any manual readings taken while a sensor was down, any change of service state, and the SQF Practitioner's signature.\nTemperature readings — the continuous per-sensor record held in the Team App, which is the temperature record required by 11.6.2.3. It is retained in full and is exportable to PDF and spreadsheet from the Temperature Monitoring page.\nTemperature alert log — the record of every alert raised, what it was, when it opened and closed, who responded and what they did. Held in the Team App and not editable after the response is recorded.\nFRM-705 Calibration Directory and Check Record — the monthly accuracy checks of the probe thermometer and the sensors, kept under FSQM-030.\nFRM-702 Non-Conforming Material Hold & Tagging Record — where product affected by an excursion is held.\nFRM-913 Facility & Equipment Inspection — where the units' condition, capacity and drainage are re-inspected.\nRetention: two years, or the shelf life of any product affected by an excursion plus twelve months, whichever is longer. This matches the retention set by FSQM-009 Part 10, so an excursion, a hold arising from it and any investigation that follows are retained on the same basis.","revision_history":"v3 — 2026-10-08 — The accuracy checks moved to the calibration record.\n\nPart 6 said these checks would move once the site had a single calibration program. FSQM-030 was issued on 2026-09-21, and the site was recording the probe and the sensors against two forms. The ice-point check of the probe and the probe-against-sensor comparison are now performed under FSQM-030 and recorded once, on FRM-705, with the other measuring devices. The monthly review on FRM-401 v3 confirms the FRM-705 result instead of repeating the readings.\n\nThe probe's ice-point tolerance is ±2 °F (it was ±1 °F here), the figure FSQM-030 has stated since it was issued.\n\nv2 — 2026-09-21 — Ice-point check of the probe thermometer.\n\nPart 6 compared each sensor against the probe thermometer and treated the probe as the reference, but nothing checked the probe. A probe and a sensor that had drifted the same way would agree, and pass together. The probe is now checked in ice water each month before it is used for that comparison: it must read 32 °F within 1 °F, or be adjusted and re-checked, or replaced. The result and the probe used are recorded on FRM-401 v2. This is the only calibration of the temperature equipment until the site writes a single calibration program covering all its measuring devices, when it moves there.\n\nRev New — written 2026-09-08 against SQF Food Safety Code: Food Manufacturing, Edition 9, element 11.6.2 Cold Storage. ISSUED 2026-09-08, approved GJM. Status active, revision New — a first issue, not a revision, so nothing is superseded and nothing archived. FRM-401 Temperature Monitoring Review is activated in the same transaction, because this procedure requires the monthly verification to be recorded on it and an active procedure requiring a draft record is the finding this wave exists to close.\n\nWHY IT EXISTS. Three sensors have logged temperatures continuously since 2026-06-24 and the Team App has displayed them since, but no document in the register cited 11.6.2 at all. The data was being collected and nobody had written down what \"good\" meant, what to do when it wasn't, or that anyone had looked. Of the four obligations in 11.6.2.3 the sensors satisfied one — records kept.\n\nTHE ALERT IS THE CHECK, AND IT WAS BUILT FIRST. 11.6.2.3 wants a stated frequency of checks and a corrective action for readings out of specification. With three to four staff, the answer was not another daily clipboard round. The Team App now examines every in-service unit every fifteen minutes, emails whoever is on the unit's recipient list, and records what the responder did. That alerting was built and proven before this procedure was written, deliberately: FSQM-018 spent months citing a \"Positive Release Procedure\" that existed nowhere, and a procedure describing an alert that had not been built would have repeated exactly that mistake.\n\nABSENCE OF DATA IS ALERTED, WHICH IS THE REAL LESSON FROM THE FIRST TEN WEEKS. Logging stopped three times, the longest gap three days and two hours, and nobody noticed. A dead sensor reads as perfect compliance, so an alert that fired only on a bad reading would have been silent through every one of those gaps. Part 5 exists because of them.\n\nWHY THE MONTHLY REVIEW IS MONTHLY. Once the system watches continuously, the human job is no longer observation — it is verification under 2.5.2.1 that the monitoring worked. A monthly review of an alert log is defensible and is likely to actually happen; a weekly one, on top of an automated check, is work that adds nothing and gets skipped.\n\nWHY 41 °F. The refrigerator has never exceeded 41 °F in the logged history and reached exactly 41 only once. A tighter limit would ship already breached, and a limit that fails on an ordinary day teaches staff to ignore alerts.\n\nOUT OF SERVICE IS A STATE, NOT A GAP. The freezer holds no product since the vegan burger line was discontinued and may be switched off. Rather than leaving it silently unmonitored or alerting on an empty unit, Part 7 makes it a recorded decision with stated conditions for coming back — including holding at limit for twenty-four hours before food goes in. The procedure survives that decision going either way.\n\nCONDITION AND DRAINAGE REUSE AN EXISTING RECORD. 11.6.2.1, .2 and .4 are one-time confirmations plus ongoing re-inspection, and FRM-913 already inspects facility condition monthly under an 11.6.2 Cold Storage line. Part 8 uses it rather than creating a second inspection, so a defect in a walk-in is found and closed the same way as a defect anywhere else in the plant.\n\nSETTLED AT ISSUE — the six floor items this procedure carried were completed on 2026-09-08 and are recorded in the body:\n\n1. The refrigerator sensor was moved to the unit's warmest point, next to the door, where 11.6.2.3 requires the monitoring equipment to sit (Part 1).\n\n2. The sensors carry no local display, so the reading is taken from the YoLink app and the Team App's Temperature Monitoring page without entering the unit — the \"easily readable and accessible\" requirement of 11.6.2.3, satisfied by the app and portal rather than a gauge at the unit (Part 1).\n\n3. The defrost and condensate drains of both units were traced and discharge to the site drain or to the outside of the facility, not onto the floor or onto stored product (11.6.2.4); photographs are retained (Part 8).\n\n4. Both units were walked and found sound, cleanable and of adequate capacity for the site's expected volume, and both hold packaged product only, with no exposed product (11.6.2.1, 11.6.2.2); photographs are retained (Part 8).\n\n5. The probe thermometer was compared against the sensors and reads within 2 °F, so Part 6's ±2 °F tolerance stands. This was a field comparison; the devices' stated-accuracy specifications were not obtained, and would matter only if a device's own rated accuracy were ±2 °F or worse, which the field agreement gives no reason to suspect.\n\n6. The vegan burger line the freezer held was discontinued in June 2026, so the freezer holds no product at present; it stays in service while it is running, and is placed out of service only when switched off (Part 1, Part 7). That date is also owed to the D-35 scope determination and to four shelf-life records that still read \"Frozen, 18 months\".\n\nThe one-time cause of the three logging gaps in the first ten weeks is known — an expired access token on the ingest daemon — and the no-data alert (Part 4) now catches a recurrence, so it is not a floor action."}$jsop401$::jsonb;
  if d.revision = 'v3' and (select bool_and(d.content->k = target->k) from unnest(array['procedure', 'records', 'form_references', 'governing_reference', 'revision_history']) k) then
    raise notice 'SOP-401: already at v3, left alone';
  elsif d.revision = 'v2' and d.status = 'active'
        and md5((select jsonb_object_agg(k, d.content->k) from unnest(array['procedure', 'records', 'form_references', 'governing_reference', 'revision_history']) k)::text) = 'a3d4fe48d5e233132bb257073a6a0522' then
    new_content := d.content || target;
    update public.sop_documents
       set content = new_content, revision = 'v3', effective_date = '2026-10-08', approved_by = 'GJM'
     where id = d.id;
  else
    raise exception 'SOP-401: not in the state this migration was written against (revision %, status %)', d.revision, d.status;
  end if;

  -- FSQM-030  New -> v2
  select id, revision, status, content into d from public.sop_documents where sop_number = 'FSQM-030';
  if not found then
    raise exception 'FSQM-030: document not found';
  end if;
  target := $jfsqm030${"form_references":"FRM-705 - Calibration Directory and Check Record\nFRM-401 - Temperature Monitoring Review (confirms each month that the probe and the sensors passed on FRM-705)\nFRM-702 - Non-Conforming Material Hold & Tagging Record\nFRM-007 - Corrective and Preventive Action record","governing_reference":"SQF Food Safety Code: Food Manufacturing, Edition 9 - 11.2.3.1 to 11.2.3.6 (Calibration).\n\nFSQM-016 Food Safety Plan - CCP 1 and CCP 2, whose monitoring devices this program keeps accurate.\nSOP-401 Temperature-Controlled Storage - whose monthly review on FRM-401 confirms the probe and sensor checks recorded under this program.\nSOP-505 and SOP-506 - oven and scale operation.\nFSQM-018 Non-Conforming Product and Equipment, and FSQM-009 CAPA - what happens when a device fails.\nFSQM-017 Validation and Verification Program - the verification schedule's calibration activity is activated against FRM-705 when this program issues.","procedure":["What is calibrated","• Every device on the FRM-705 directory: the probe thermometer, the walk-in refrigerator and freezer sensors, the oven's temperature display and bake timer, the two bench scales, and the vacuum sealer's gauge.","• A device is added to the directory when it is bought, before it is used for monitoring, and removed only when it leaves the site (SQF 11.2.3.6).","References and methods","• The probe thermometer is the site's temperature reference. It is checked every month at two points, in ice water (32°F) and in boiling water, each within ±2°F, and both are recorded on FRM-705. It is checked before it is used for the sensor and oven checks.","• The oven's display is checked against the probe at the centre of the rack after preheat, and passes if the oven is no more than 5°F cooler than its display. Its bake timer is checked against a phone clock over a full bake, within 30 seconds.","• The scales are checked with a 25 lb test weight that carries a calibration certificate traceable to national standards, and pass within ±0.25 lb (±1%). The scales weigh up to about 30 lb, so 25 lb tests them in the range they are used in; a scale outside that is re-calibrated with its own calibration routine as its manual describes, then checked again.","• The refrigerator and freezer sensors are compared with the probe every month, both reading the same place at the same time, within ±2°F, and recorded on FRM-705. A sensor outside that is treated as suspect: its readings are confirmed with the probe until it is replaced or passes a check.","> THE REFERENCE IS NOT CERTIFIED, AND THAT IS STATED RATHER THAN HIDDEN. SQF 11.2.3.2 asks for calibration against national or international standards, or, where the site does not hold them, evidence for the method it uses instead. The scales are checked against a certified test weight, which is traceable to national standards. The site holds no certified thermometer, and for temperature the two-point check is that evidence: a thermometer that reads 32°F in ice water and the boiling point in boiling water is right across the range between them, which covers the 350°F oven only by extension - so the oven's own tolerance is set on the conservative side.","> The Team App's temperature report is software used for monitoring. It is validated each month by the same sensor comparison, because a report that agrees with the probe is reporting what the sensor measured (SQF 11.2.3.1).","Frequency","• Every device on the directory is checked monthly, in one session, and recorded as one FRM-705 entry.","• A device is also checked before it is used again after it is repaired, moved, dropped or suspected of reading wrongly.","• Where a device's manual sets a shorter interval, the manual's interval applies (SQF 11.2.3.3).","The vacuum gauge is not relied on","> CCP 2 is judged by a visual check of every pouch and by the pull test, not by the gauge, and the gauge has never been checked. FRM-606 records its reading without judging it. It stays on the directory, marked Not relied on, and is calibrated before any CCP 2 limit is set on it under FSQM-016.","When a device fails","• The device is tagged DO NOT USE and the SQF Practitioner is told the same day.","• The SQF Practitioner decides which product was made with it since its last pass and whether that product is affected. For the oven, that means whether each bake since the last pass reached the CCP 1 limit.","• Affected product is held on FRM-702 and dispositioned under FSQM-018; a failure of a device that monitors a CCP is also raised as a corrective action on FRM-007 under FSQM-009 (SQF 11.2.3.4).","• The device is repaired, re-calibrated or replaced, and passes a check, before it is used again.","Protection","• Only the SQF Practitioner adjusts a device's calibration or an oven set point to compensate for one.","• The probe thermometer and the test weight are kept clean and in their case or container when not in use; the scales are not moved except for cleaning, and are checked again if they are (SQF 11.2.3.5)."],"records":"• FRM-705 entries, one per month, reviewed and signed by the SQF Practitioner\n• FRM-702 and FRM-007 records arising from a failed device\n• Service or calibration reports from an outside provider, attached to the FRM-705 entry for that month","revision_history":"v2 - 2026-10-08 - Every calibration is recorded on FRM-705.\n\nThe probe's ice-point check and the refrigerator and freezer sensor comparisons were performed under SOP-401 and recorded on FRM-401, while everything else was recorded on FRM-705. They are now recorded on FRM-705 with the other devices (owner's decision, 2026-10-08), and FRM-401 confirms the result. FRM-705 v2 gives the probe one row for each of its two checks. No tolerance changes in this program: the probe and the sensors were already ±2°F here; SOP-401 said ±1°F for the ice point and is revised to match.\n\nNew - 2026-09-21 - DRAFT under D-28, for the six Non-Compliant findings against 11.2.3.\n\nWHAT THE SITE DID BEFORE: the oven was checked with a thermometer from time to time and the scales with test weights on site, without a schedule or a record; the probe thermometer was ice-point checked monthly under SOP-401; the vacuum gauge was never checked. This program puts the checks that were happening on a schedule and a record, rather than inventing new ones.\n\nNO CERTIFIED REFERENCE (owner's decision, 2026-09-21): the current probe stays the reference, justified by a two-point check, with the oven tolerance set conservatively because the probe is proven only at 32°F and the boiling point.\n\nTEST WEIGHT (owner, 2026-09-21): a 25 lb certified test weight for the scales, which weigh up to about 30 lb. The 100 g weights on site tested only the bottom of the range, where scales rarely go wrong.\n\nTOLERANCES ARE PROPOSED for the owner's review: oven no more than 5°F cooler than its display, timer ±30 s, scales ±1%, probe and sensors ±2°F (the last already in force under SOP-401)."}$jfsqm030$::jsonb;
  if d.revision = 'v2' and (select bool_and(d.content->k = target->k) from unnest(array['procedure', 'records', 'form_references', 'governing_reference', 'revision_history']) k) then
    raise notice 'FSQM-030: already at v2, left alone';
  elsif d.revision = 'New' and d.status = 'active'
        and md5((select jsonb_object_agg(k, d.content->k) from unnest(array['procedure', 'records', 'form_references', 'governing_reference', 'revision_history']) k)::text) = 'c50096da6de5a1e9a267ec87094b0e96' then
    new_content := d.content || target;
    update public.sop_documents
       set content = new_content, revision = 'v2', effective_date = '2026-10-08', approved_by = 'GJM'
     where id = d.id;
  else
    raise exception 'FSQM-030: not in the state this migration was written against (revision %, status %)', d.revision, d.status;
  end if;

  -- After: every answer id that left FRM-401 is one this file meant to remove, and nothing else went.
  if (select count(*) from public.sop_documents x,
             jsonb_array_elements(x.content->'form_schema'->'sections') s,
             jsonb_array_elements(s->'fields') f
       where x.sop_number = 'FRM-401') <> 17 then
    raise exception 'FRM-401: field count is not 17 after the change';
  end if;
  if (select jsonb_array_length(f->'rows'->'labels') from public.sop_documents x,
             jsonb_array_elements(x.content->'form_schema'->'sections') s,
             jsonb_array_elements(s->'fields') f
       where x.sop_number = 'FRM-705' and f->>'id' = 'devices') <> 9 then
    raise exception 'FRM-705: the directory does not hold 9 rows after the change';
  end if;
end $$;
